template.body:
{% raw %}
<style>
  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
  .tb-wrap { max-width: 1200px; margin: 0 auto; padding: 1.5rem; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif; color: #e0e0e0; }
  .tb-head { margin-bottom: 1.5rem; }
  .tb-head h1 { font-size: 1.75rem; font-weight: 700; color: #fff; letter-spacing: -0.02em; }
  .tb-head p { color: #6a6a8e; font-size: 0.88rem; margin-top: 0.25rem; }

  .tb-summary { display: flex; gap: 0.75rem; margin-bottom: 1.75rem; flex-wrap: wrap; }
  .tb-stat { background: #16213e; border: 1px solid #252545; border-radius: 10px; padding: 0.85rem 1.25rem; flex: 1; min-width: 110px; text-align: center; }
  .tb-stat-val { display: block; font-size: 1.75rem; font-weight: 700; line-height: 1.2; }
  .tb-stat-lbl { display: block; font-size: 0.7rem; color: #6a6a8e; text-transform: uppercase; letter-spacing: 0.06em; margin-top: 0.2rem; }
  .tb-c-todo { color: #7c83ff; }
  .tb-c-prog { color: #f0a500; }
  .tb-c-done { color: #2ecc71; }
  .tb-c-over { color: #e74c3c; }

  .tb-board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; align-items: start; }
  @media (max-width: 920px) { .tb-board { grid-template-columns: 1fr; } }

  .tb-col { background: #0f0f23; border: 1px solid #252545; border-radius: 12px; padding: 0.85rem; }
  .tb-col-hdr { display: flex; align-items: center; gap: 0.5rem; padding-bottom: 0.7rem; margin-bottom: 0.75rem; border-bottom: 2px solid #252545; }
  .tb-col-hdr h2 { font-size: 0.95rem; font-weight: 600; color: #fff; flex: 1; }
  .tb-dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }
  .tb-dot-todo { background: #7c83ff; }
  .tb-dot-in-progress { background: #f0a500; }
  .tb-dot-done { background: #2ecc71; }
  .tb-col-cnt { background: #1e1e3a; color: #8888aa; font-size: 0.75rem; font-weight: 600; padding: 0.1rem 0.55rem; border-radius: 10px; }

  .tb-cards { display: flex; flex-direction: column; gap: 0.6rem; min-height: 48px; }
  .tb-card { background: #16213e; border: 1px solid #252545; border-radius: 10px; padding: 0.9rem; transition: border-color 0.15s, box-shadow 0.15s; }
  .tb-card:hover { border-color: #3a3a5a; box-shadow: 0 2px 12px rgba(0,0,0,0.25); }
  .tb-card-over { border-left: 3px solid #e74c3c; }

  .tb-card-top { display: flex; align-items: center; gap: 0.45rem; margin-bottom: 0.5rem; flex-wrap: wrap; }
  .tb-badge { font-size: 0.65rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 0.18rem 0.5rem; border-radius: 4px; line-height: 1.3; }
  .tb-b-low { background: #14302a; color: #2ecc71; }
  .tb-b-medium { background: #14253a; color: #5dade2; }
  .tb-b-high { background: #33291a; color: #f0a500; }
  .tb-b-urgent { background: #331a1a; color: #e74c3c; }
  .tb-over-tag { font-size: 0.6rem; font-weight: 700; color: #e74c3c; background: #331a1a; padding: 0.15rem 0.45rem; border-radius: 4px; margin-left: auto; white-space: nowrap; }

  .tb-card-title { font-size: 0.92rem; font-weight: 600; color: #eee; line-height: 1.35; margin-bottom: 0.35rem; }
  .tb-card-desc { font-size: 0.78rem; color: #6a6a8e; line-height: 1.45; margin-bottom: 0.55rem; }

  .tb-tags { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-bottom: 0.65rem; }
  .tb-tag { font-size: 0.68rem; background: #0f0f23; color: #8888aa; padding: 0.12rem 0.45rem; border-radius: 3px; border: 1px solid #252545; }

  .tb-card-foot { display: flex; align-items: center; justify-content: space-between; padding-top: 0.55rem; border-top: 1px solid #252545; }
  .tb-assignee { display: flex; align-items: center; gap: 0.35rem; }
  .tb-avatar { width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.65rem; font-weight: 700; color: #fff; text-transform: uppercase; flex-shrink: 0; }
  .tb-avatar-0 { background: #7c83ff; }
  .tb-avatar-1 { background: #e94560; }
  .tb-avatar-2 { background: #2ecc71; }
  .tb-avatar-3 { background: #f0a500; }
  .tb-assignee-name { font-size: 0.75rem; color: #8888aa; }
  .tb-due { font-size: 0.72rem; color: #6a6a8e; white-space: nowrap; }
  .tb-due-over { color: #e74c3c; font-weight: 600; }

  .tb-empty { text-align: center; color: #3a3a5a; font-size: 0.82rem; padding: 1.5rem 0; font-style: italic; }
  .tb-foot { text-align: center; margin-top: 2rem; color: #3a3a5a; font-size: 0.72rem; }
</style>
{% endraw %}

<div class="tb-wrap">
  <div class="tb-head">
    <h1>Task Board</h1>
    <p>Sprint 4 · Week of Jul 27, 2026</p>
  </div>

  <div class="tb-summary">
    <div class="tb-stat">
      <span class="tb-stat-val">{{ stats.total }}</span>
      <span class="tb-stat-lbl">Total</span>
    </div>
    <div class="tb-stat">
      <span class="tb-stat-val tb-c-todo">{{ stats.todo_count }}</span>
      <span class="tb-stat-lbl">To Do</span>
    </div>
    <div class="tb-stat">
      <span class="tb-stat-val tb-c-prog">{{ stats.in_progress_count }}</span>
      <span class="tb-stat-lbl">In Progress</span>
    </div>
    <div class="tb-stat">
      <span class="tb-stat-val tb-c-done">{{ stats.done_count }}</span>
      <span class="tb-stat-lbl">Done</span>
    </div>
    <div class="tb-stat">
      <span class="tb-stat-val tb-c-over">{{ stats.overdue_count }}</span>
      <span class="tb-stat-lbl">Overdue</span>
    </div>
  </div>

  <div class="tb-board">
    {% for col_id, col_name, col_tasks in columns_list %}
    <div class="tb-col">
      <div class="tb-col-hdr">
        <span class="tb-dot tb-dot-{{ col_id }}"></span>
        <h2>{{ col_name }}</h2>
        <span class="tb-col-cnt">{{ col_tasks|length }}</span>
      </div>
      <div class="tb-cards">
        {% for task in col_tasks %}
        <div class="tb-card{% if task.is_overdue %} tb-card-over{% endif %}">
          <div class="tb-card-top">
            <span class="tb-badge tb-b-{{ task.priority|default('medium', true) }}">{{ task.priority|default('medium', true) }}</span>
            {% if task.is_overdue %}
            <span class="tb-over-tag">Overdue</span>
            {% endif %}
          </div>
          <div class="tb-card-title">{{ task.title|default('Untitled', true) }}</div>
          {% if task.description|default('', true) %}
          <div class="tb-card-desc">{{ task.description }}</div>
          {% endif %}
          {% if task.tags|default([], true)|length > 0 %}
          <div class="tb-tags">
            {% for tag in task.tags %}
            <span class="tb-tag">{{ tag }}</span>
            {% endfor %}
          </div>
          {% endif %}
          <div class="tb-card-foot">
            <div class="tb-assignee">
              {% set avatar_idx = loop.index0 % 4 %}
              <span class="tb-avatar tb-avatar-{{ avatar_idx }}">{{ task.assignee|default('U', true)|truncate(1, True, '') }}</span>
              <span class="tb-assignee-name">{{ task.assignee|default('Unassigned', true) }}</span>
            </div>
            <span class="tb-due{% if task.is_overdue %} tb-due-over{% endif %}">{{ task.due_date|default('No date', true) }}</span>
          </div>
        </div>
        {% endfor %}
        {% if col_tasks|length == 0 %}
        <div class="tb-empty">No tasks</div>
        {% endif %}
      </div>
    </div>
    {% endfor %}
  </div>

  <div class="tb-foot">Powered by PythonAppFoundry · Task Board v1.0.0</div>
</div>
